        internal static string ComputeRefListFingerprint(IReadOnlyList<string>? assemblyNames)
        {
            if (assemblyNames == null || assemblyNames.Count == 0)
                return "none";
            var sb = new StringBuilder();
            foreach (var name in assemblyNames.OrderBy(n => n, StringComparer.OrdinalIgnoreCase))
                sb.Append($"{name}|");
            return Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(sb.ToString())))[..16];
        }

        /// <summary>
        /// 按缓存键读取已编译结果（不含缓存写入逻辑）。

        public static ScriptSandbox GetOrCreate(string cacheKey, string? refDir)
        {
            var slot = _pool.GetOrAdd(cacheKey, k => new SandboxSlot(new ScriptSandbox($"ScriptSandboxPool_{k[..8]}", refDir)));
            slot.LastUsed = DateTime.UtcNow;
            EvictIfNeeded();
            return slot.Sandbox;
        }

